fn bitwise_and(x1: &Vec<u8>, x2: &Vec<u8>) -> Vec<u8> {
    // Precondition: the two vectors must have the same length.
    assert_eq!(x1.len(), x2.len(), "Input vectors must have the same length");

    // Compute element-wise bitwise AND
    x1.iter()
      .zip(x2.iter())
      .map(|(&a, &b)| {
          let c = a & b;
          // Properties we expect:
          // 1. c == a & b
          debug_assert_eq!(c, a & b);
          // 2. commutativity: a & b == b & a
          debug_assert_eq!(a & b, b & a);
          // 3. a & 0 == 0
          debug_assert_eq!(a & 0, 0);
          debug_assert_eq!(b & 0, 0);
          // 4. a & a == a
          debug_assert_eq!(a & a, a);
          debug_assert_eq!(b & b, b);
          // 5. c <= a and c <= b
          debug_assert!(c <= a);
          debug_assert!(c <= b);
          c
      })
      .collect()
}

